# build_system_prompt 함수 전체를 정규식으로 교체
pattern = re.compile(
    r'^def build_system_prompt\(.*?\n(?=^def )',
    re.MULTILINE | re.DOTALL,
)

if not pattern.search(src):
    print("ERROR: build_system_prompt 함수를 찾지 못했습니다.", file=sys.stderr)
    sys.exit(1)

new_src = pattern.sub(NEW_FUNC + "\n\n", src, count=1)

if new_src == src:
    print("ERROR: 치환이 발생하지 않았습니다.", file=sys.stderr)
    sys.exit(1)

TARGET.write_text(new_src, encoding="utf-8")
print(f"OK: {TARGET} 패치 완료")
